<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>گزارش دریافت‌های نقدی و چکی</title><style>@font-face{font-family:Vazirmatn;src:url('{{ asset('fonts/vazirmatn/Vazirmatn-Regular.woff2') }}')}body{font-family:Vazirmatn,Tahoma,sans-serif;font-size:11px;color:#23455b}h1{font-size:20px;font-weight:500}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #d8e3eb;text-align:right}thead{display:table-header-group}tr{break-inside:avoid}button{padding:10px}@media print{button{display:none}@page{size:A4 landscape;margin:12mm}}</style></head><body><button onclick="window.print()">چاپ / ذخیره PDF</button><h1>دریافت‌های نقدی و چکی</h1><p>{{ request('scope')==='due'?'گزارش سررسید همهٔ چک‌ها؛ مستقل از بازهٔ دریافت':$filters['date_from'].' تا '.$filters['date_to'] }} · مبالغ ریال · چک دریافت‌شده به معنی وصول وجه نیست.</p><p>{{ $rows->count() }} پرداخت · جمع {{ number_format($rows->sum('amount')) }} ریال</p><table><thead><tr><th>تاریخ دریافت</th><th>مشتری</th><th>روش</th><th>مبلغ</th><th>بانک</th><th>چک / پیگیری</th><th>سررسید</th><th>صیادی</th><th>فاکتور</th><th>ثبت‌کننده</th></tr></thead><tbody>@foreach($rows as $r)<tr><td>{{ \App\Support\JalaliDate::date($r->received_at) }}</td><td>{{ $r->customer_name }}</td><td>{{ $r->method==='cheque'?'چکی':($r->method==='online'?'آنلاین':'نقدی') }}</td><td>{{ number_format($r->amount) }}</td><td>{{ $r->bank }}</td><td>{{ $r->cheque_number??$r->payment_identifier }}</td><td>{{ \App\Support\JalaliDate::date($r->due_date) }}</td><td>{{ $r->method==='cheque'?($r->status==='registered'?'ثبت‌شده':($r->status==='unregistered'?'ثبت‌نشده':'نامشخص')):'—' }}</td><td>{{ $r->invoice_uuid }}</td><td>{{ $r->creator }}</td></tr>@endforeach</tbody></table></body></html>
